import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"Ceph Performance Meeting 2022-03-31","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-03-31","date":"2022-03-31T00:00:00.000Z","updated":"2022-04-01T00:00:00.000Z","tags":["Ceph","性能优化","分布式存储","AVL分配器","测试与验证","PR"],"categories":["会议纪要","技术讨论"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-03-31.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-03-31.md","lastUpdated":1780459816000}'),l={name:"posts/2022/Ceph_Performance_Meeting_2022-03-31.md"};function o(n,e,s,h,c,u){return a(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>Pull Requests (PRs) 动态</strong>: 本次会议讨论了Quincy版本中的一些PR，包括RGW多站点resharding和性能相关的PR。Gabby的PR主要涉及代码清理，不影响性能。另一个关于tracer的PR正在进行更多测试以确保稳定性。</li><li><strong>性能回归问题</strong>: 团队正在追踪Quincy版本中的写入性能回归问题，初步怀疑与AVL分配器的更改有关。</li><li><strong>分配器行为变化</strong>: 讨论了分配器在First Fit和Best Fit模式下的行为差异，以及这些模式如何影响性能。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ul><li><strong>性能回归问题分析</strong>: 通过二分法定位到特定提交，该提交涉及AVL分配器的更改。团队正在测试回滚该更改后的性能影响。</li><li><strong>硬件差异对性能的影响</strong>: 讨论了不同硬件（如AMD和Intel）上性能表现的差异，以及如何通过测试来验证这些差异。</li><li><strong>分配器行为对性能的影响</strong>: 分析了AVL分配器在First Fit和Best Fit模式下的行为差异，探讨了其对性能的可能影响。</li></ul><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li><strong>继续测试和分析</strong>: 团队将继续测试回滚AVL分配器更改后的性能，并探索其他可能影响性能的因素。</li><li><strong>使用性能直方图</strong>: 计划使用性能直方图来分析分配器的输出，以更好地理解其对性能的影响。</li></ul><h4 id="后续的行动计划" tabindex="-1">后续的行动计划 <a class="header-anchor" href="#后续的行动计划" aria-label="Permalink to &quot;后续的行动计划&quot;">​</a></h4><ul><li><strong>详细测试计划</strong>: 包括使用fio进行更详细的性能测试，特别是在不同硬件上的测试。</li><li><strong>性能直方图分析</strong>: 收集和分析性能直方图数据，以评估分配器的输出对性能的具体影响。</li><li><strong>硬件和软件配置的同步</strong>: 确保测试环境和配置的一致性，以便更准确地比较不同硬件和软件配置下的性能表现。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li><strong>会议结束</strong>: 会议在讨论完所有议题后结束，团队成员将继续进行各自的测试和分析工作。</li></ul><h3 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h3><ul><li>Pull Requests (PRs)</li><li>RGW Multi-Site Resharding</li><li>Quincy</li><li>AVL Allocator</li><li>First Fit vs Best Fit</li><li>Performance Regression</li><li>fio</li><li>Performance Histogram</li></ul>',13)])])}const _=t(l,[["render",o]]);export{g as __pageData,_ as default};
